/* Banco de preguntas. Formato MC: o[0] es SIEMPRE la correcta; la app baraja las opciones al mostrarlas. */
(function () {
  const TOPICS = {
    met: 'Metodología de diseño',
    er: 'Modelo Entidad-Relación (Chen)',
    avz: 'ER avanzado: herencia, ternarias, restricciones',
    rel: 'Modelo relacional y transformación',
    pg: 'Diagramas de Pata de Gallo',
    sql: 'SQL: DDL, DML y consultas',
    lab: 'Laboratorios en PostgreSQL',
    norm: 'Normalización'
  };

  let n = 0;
  const bank = [];
  const Q = (t, q, ok, wrong, e) => bank.push({ id: 'q' + (++n), t, q, o: [ok].concat(wrong), a: 0, e });

  /* ---------------- MET ---------------- */
  Q('met', '¿Cuál es el primer paso de la metodología de diseño de una base de datos?', 'Determinar el Universo del Discurso (UD) a partir de las vistas de los usuarios', ['Crear las tablas en el SGBD', 'Normalizar el modelo relacional', 'Escribir las sentencias INSERT'], 'La metodología parte del Universo del Discurso: la realidad que se quiere modelar, vista desde los distintos usuarios.');
  Q('met', 'Un modelo conceptual (como el Entidad-Relación) debe ser…', 'Independiente de cualquier Sistema Gestor de Bases de Datos', ['Específico del SGBD elegido', 'Escrito en SQL', 'Un script con índices y restricciones físicas'], 'El modelo conceptual es una vista abstracta y global; no depende de herramientas informáticas ni de un SGBD.');
  Q('met', '¿Quién propuso el Modelo Entidad-Relación y en qué año?', 'Peter Chen, 1976', ['Edgar F. Codd, 1970', 'Peter Chen, 1990', 'Codd, 1976'], 'Chen (1976) propuso el modelo E/R; Codd (1970) el modelo relacional.');
  Q('met', '¿Quién propuso el modelo relacional y en qué año?', 'Edgar F. Codd, 1970', ['Peter Chen, 1976', 'Edgar F. Codd, 1990', 'Chen, 1970'], 'El modelo relacional es de Codd (1970), basado en teoría de conjuntos y lógica de predicados.');
  Q('met', 'El modelo relacional se apoya en…', 'Teoría de conjuntos, lógica de predicados de primer orden y álgebra relacional', ['Teoría de grafos y cálculo diferencial', 'Programación orientada a objetos y UML', 'Redes neuronales y estadística'], 'Es un modelo definido con rigor matemático a partir de las relaciones como conjuntos de datos.');
  Q('met', 'La normalización dentro de la metodología sirve para…', 'Perfeccionar el modelo relacional eliminando redundancia y duplicaciones innecesarias', ['Dibujar el diagrama Entidad-Relación', 'Crear los índices del modelo físico', 'Asignar permisos a los usuarios'], 'Se aplica al modelo relacional (lógico) antes del modelo físico.');
  Q('met', '¿Qué describe el modelo físico?', 'Cómo se almacenarán los datos según el SGBD elegido: sentencias DDL, tablas, relaciones, índices y restricciones', ['Una vista abstracta e independiente del SGBD', 'Solo las entidades y sus atributos', 'Las dependencias funcionales de cada tabla'], 'El modelo físico es el nivel más bajo de abstracción y depende del SGBD.');
  Q('met', 'Orden correcto de las etapas de diseño:', 'Universo del discurso → modelo conceptual (E/R) → modelo lógico (relacional) → normalización → modelo físico', ['Modelo físico → modelo relacional → E/R → universo del discurso', 'E/R → universo del discurso → físico → relacional', 'Normalización → E/R → UD → físico'], 'De lo abstracto a lo concreto: UD, conceptual, lógico, normalización y físico.');
  Q('met', '¿Cuál de estos es un modelo LÓGICO (no conceptual)?', 'Modelo relacional', ['Modelo Entidad-Relación', 'Modelo semántico de datos', 'Diagrama de Chen'], 'Entre los modelos lógicos están el jerárquico, Codasyl y el relacional. El E/R es conceptual.');
  Q('met', 'Respecto a la evaluación del curso Sistemas Transaccionales y BD, ¿cuál es el valor del Momento 3?', '70 %', ['30 %', '0 %', '50 %'], 'Según la presentación del curso: Momento 1 = 0 %, Momento 2 = 30 %, Momento 3 = 70 %.');

  /* ---------------- ER ---------------- */
  Q('er', 'En el modelo E/R, una entidad es…', 'Cualquier cosa, objeto o concepto (físico o abstracto) distinguible, de la que se quiere almacenar información', ['Una columna de una tabla', 'Una fila de una tabla', 'Un valor que toma un atributo'], 'Física: Persona, Libro, Avión. Abstracta: Viaje, Receta.');
  Q('er', '¿Cómo se representa gráficamente una entidad débil en el diagrama de Chen?', 'Con dos rectángulos concéntricos', ['Con un rombo doble', 'Con un óvalo punteado', 'Con un rectángulo de línea punteada'], 'La débil depende de otra entidad: no tiene sentido por sí misma (ej. Cuenta depende de Cliente).');
  Q('er', 'Un atributo cuyo valor se calcula a partir de otro (por ejemplo, edad a partir de fechaNacimiento) es…', 'Derivado', ['Multivaluado', 'Compuesto', 'Clave alternativa'], 'Los atributos derivados se dibujan con línea punteada y desaparecen al pasar al modelo relacional.');
  Q('er', 'Un atributo que puede almacenar varios valores para un mismo ejemplar (por ejemplo, varios teléfonos) es…', 'Multivaluado', ['Derivado', 'Simple y univaluado', 'Opcional'], 'En el modelo relacional genera una tabla propia.');
  Q('er', 'fechaNacimiento formado por día, mes y año es un atributo…', 'Compuesto', ['Multivaluado', 'Derivado', 'Opcional'], 'Los compuestos se descomponen en atributos simples al transformar.');
  Q('er', 'Un atributo opcional es aquel que…', 'Puede quedar vacío (nulo)', ['Se calcula con una fórmula', 'Siempre toma varios valores', 'Identifica de forma única al ejemplar'], 'En SQL corresponde a una columna sin NOT NULL.');
  Q('er', 'La clave principal de una entidad…', 'Identifica de forma única a cada ejemplar y no admite valores nulos', ['Puede repetirse entre ejemplares', 'Siempre es un atributo compuesto', 'Es siempre un atributo multivaluado'], 'Puede ser un atributo o una combinación de atributos.');
  Q('er', 'Una clave alternativa es…', 'Otro atributo (o conjunto) que también identifica de forma única a un ejemplar', ['La clave que se copia en otra tabla', 'Un atributo derivado', 'La clave de la entidad débil'], 'Ejemplo: Estudiante con código e id. Se transforma en una clave alternativa (UNIQUE).');
  Q('er', '¿Qué es el dominio de un atributo?', 'El conjunto de valores posibles que puede tomar', ['El nombre de la entidad dueña del atributo', 'La cardinalidad máxima de la relación', 'La tabla donde se guarda'], 'Ejemplo: dominio de género = {F, M}.');
  Q('er', 'El grado de una relación indica…', 'El número de entidades que participan en ella', ['El número máximo de ejemplares relacionados', 'El número de atributos de la relación', 'La clave primaria de la relación'], 'Dos entidades → binaria; tres → ternaria.');
  Q('er', 'Una relación reflexiva (o recursiva) es…', 'Una relación binaria que conecta una entidad consigo misma, usando roles', ['Una relación entre tres entidades', 'Una relación que no tiene atributos', 'Una relación entre entidad fuerte y débil'], 'Ejemplo: Empleado supervisa a Empleado (roles es_supervisor / es_supervisado).');
  Q('er', 'La cardinalidad (0,n) significa…', 'Cero a muchos', ['Uno a muchos', 'Cero a uno', 'Exactamente uno'], '(0,1) cero a uno; (1,1) exactamente uno; (0,n) cero a muchos; (1,n) uno a muchos.');
  Q('er', 'La cardinalidad (1,1) significa…', 'Exactamente uno (mínimo uno y máximo uno)', ['Cero a uno', 'Uno a muchos', 'Cero a muchos'], 'Participación obligatoria y única.');
  Q('er', 'La correspondencia (1:1, 1:N, N:M) se obtiene…', 'Analizando los máximos de las cardinalidades de la relación', ['Analizando los mínimos de las cardinalidades', 'Contando los atributos de cada entidad', 'Mirando las claves primarias'], 'La correspondencia es el número máximo de ejemplares con los que se relaciona un ejemplar.');
  Q('er', 'Si en una relación los máximos de ambos lados son "n", la correspondencia es…', 'N:M (muchos a muchos)', ['1:N', '1:1', 'N:1 con clave foránea'], 'N:M se transforma en una tabla nueva.');
  Q('er', 'En una generalización/especialización, la cardinalidad del supertipo hacia el subtipo se lee…', '(1,1) en el supertipo y (0,1) en los subtipos', ['(0,n) en el supertipo y (1,1) en los subtipos', '(1,n) en ambos', '(0,1) en el supertipo y (1,n) en los subtipos'], 'La relación es "es un": todo subtipo es también supertipo, pero no al revés.');
  Q('er', 'En la generalización, ¿dónde se colocan los atributos comunes y el identificador?', 'En el supertipo', ['En cada subtipo', 'En la relación "es un"', 'En ninguna entidad'], 'Las relaciones que afectan a todos los subtipos también se asocian al supertipo.');
  Q('er', 'En la técnica clásica de análisis de enunciados, los sustantivos suelen indicar… y los verbos…', 'Entidades, atributos y relaciones / las relaciones', ['Relaciones / las entidades', 'Cardinalidades / los atributos', 'Claves primarias / las claves foráneas'], 'Se extraen sustantivos, se filtran los conceptos abstractos irrelevantes y se dejan los objetos persistentes del dominio.');
  Q('er', 'En el enunciado "Una empresa vende productos a varios clientes…", ¿por qué NO se modela EMPRESA como entidad?', 'Porque es la organización dueña del sistema: solo tiene una instancia y no se guarda información sobre ella', ['Porque las entidades no pueden tener nombre propio', 'Porque solo se modelan sustantivos en plural', 'Porque toda entidad necesita al menos tres atributos'], 'Pregunta de la clase de ejercicios (Sesión 4).');
  Q('er', 'Una relación puede tener atributos propios. Por ejemplo, en "Profesor imparte Curso" el atributo fechaInicio pertenece a…', 'La relación imparte', ['La entidad Profesor', 'La entidad Curso', 'Ninguna'], 'Son atributos que dependen del par de ejemplares relacionados.');

  /* ---------------- AVZ ---------------- */
  Q('avz', 'Hay dependencia en existencia cuando…', 'Los ejemplares de la entidad débil no pueden existir si desaparece el ejemplar de la entidad fuerte de la que dependen', ['La entidad débil se identifica solo con sus propios atributos', 'Dos relaciones son exclusivas', 'La relación tiene tres entidades'], 'Es la condición básica de la entidad débil.');
  Q('avz', 'Hay dependencia en identificación cuando…', 'Además de la dependencia en existencia, la entidad débil no se identifica por sí misma y exige añadir la clave de la entidad fuerte', ['La entidad débil puede identificarse sin la entidad fuerte', 'Los subtipos se solapan', 'La relación es reflexiva'], 'Ejemplo: Edicion se identifica por (cod_Curso, num_Edicion).');
  Q('avz', 'Sobre dependencias en existencia e identificación es correcto afirmar que…', 'Toda dependencia en identificación es una dependencia en existencia, pero no al revés', ['Toda dependencia en existencia es de identificación', 'Son exactamente lo mismo', 'Ninguna dependencia en identificación es de existencia'], 'La identificación añade una condición extra a la existencia.');
  Q('avz', 'Curso (1,n) tiene Edición (1,1), donde Edición se identifica con cod_Curso + num_Edicion. ¿Qué tipo de dependencia es?', 'En identificación (y por tanto también en existencia)', ['Solo en existencia', 'Ninguna: son entidades fuertes', 'Es una relación reflexiva'], 'La clave de Edición incluye la clave de Curso.');
  Q('avz', 'Una Persona puede ser Profesor y Estudiante a la vez. ¿Qué característica tiene esta especialización?', 'Solapamiento', ['Exclusividad', 'Totalidad obligatoria', 'Agregación'], 'Habrá solapamiento si un mismo ejemplar del supertipo puede pertenecer a más de un subtipo.');
  Q('avz', 'Un Profesor es de Planta u Ocasional, pero no ambos. Esto es…', 'Exclusividad (subtipos disjuntos)', ['Solapamiento', 'Parcialidad', 'Agregación'], 'Exclusividad: un ejemplar del supertipo solo puede pertenecer a UNO de los subtipos.');
  Q('avz', '"Todo empleado es un Profesor o un Administrativo" es un ejemplo de…', 'Totalidad', ['Parcialidad', 'Solapamiento', 'Exclusión'], 'Totalidad: todo ejemplar del supertipo tiene que pertenecer obligatoriamente a algún subtipo.');
  Q('avz', 'Parcialidad en una especialización significa que…', 'No es obligatorio que un ejemplar del supertipo pertenezca a algún subtipo', ['Todo ejemplar debe pertenecer a un subtipo', 'Un ejemplar puede pertenecer a varios subtipos', 'Los subtipos no tienen atributos propios'], 'Es lo contrario de la totalidad.');
  Q('avz', 'Una relación ternaria suele cumplir que…', 'Participan 3 entidades, hay 6 lecturas coherentes y normalmente es N:M, a menudo en el tiempo', ['Participan 2 entidades y 3 atributos', 'Siempre es 1:1', 'Solo tiene 2 lecturas posibles'], 'Si no hay lectura coherente en algún sentido, probablemente no deba modelarse como ternaria.');
  Q('avz', 'La agregación se usa cuando…', 'Se necesita relacionar una interrelación con otra entidad, algo que el modelo E/R básico no permite', ['Se quiere eliminar un atributo derivado', 'Se quiere convertir una entidad débil en fuerte', 'Hay un atributo multivaluado'], 'Se crea un tipo de entidad compuesto (relación + entidades vinculadas) que ya puede relacionarse con otras. Ej.: Profesor explica Asignatura y utiliza Medio.');
  Q('avz', '"Un proyecto se asigna a empleados o a empresas contratistas, pero no a ambos" es una restricción de…', 'Exclusividad', ['Inclusión', 'Inclusividad', 'Totalidad'], 'Exclusividad: cada ejemplar de A solo puede relacionarse con B a través de R1 o R2, pero no ambas.');
  Q('avz', '"Un profesor no puede impartir y capacitarse en el mismo curso" es una restricción de…', 'Exclusión', ['Exclusividad', 'Inclusión', 'Agregación'], 'Exclusión: afecta al mismo par de ejemplares (a1, b1), no a la entidad completa.');
  Q('avz', '"Solo pueden impartir cursos los profesores que se hayan capacitado al menos en un curso cualquiera" es una restricción de…', 'Inclusividad', ['Exclusión', 'Exclusividad', 'Inclusión'], 'Inclusividad: todo ejemplar de A que participa en R2 debe haber participado en R1 (con cualquier ejemplar de B).');
  Q('avz', '"Para que una persona sea liquidada de su empresa, esa misma persona tuvo que ser contratada previamente por ella" es una restricción de…', 'Inclusión', ['Inclusividad', 'Exclusión', 'Exclusividad'], 'Inclusión: el par (a1, b1) debe estar asociado antes por R1 para poder asociarse por R2.');
  Q('avz', '¿Cómo se implementan en SQL las restricciones de exclusividad/exclusión entre interrelaciones?', 'Mediante restricciones adicionales en código SQL, por ejemplo cláusulas CHECK', ['Se resuelven automáticamente al crear las claves foráneas', 'No se pueden implementar', 'Añadiendo más atributos derivados'], 'Presentación: "Para soportar las restricciones de interrelaciones debemos definir las restricciones pertinentes a través de código SQL".');

  /* ---------------- REL ---------------- */
  Q('rel', 'En el modelo relacional, el término "relación" significa…', 'Una tabla (estructura bidimensional de filas y columnas)', ['La asociación entre dos entidades', 'Una clave foránea', 'Un rombo del diagrama de Chen'], 'No hay que confundirlo con la "relación" del modelo E/R.');
  Q('rel', 'Al transformar el modelo E/R al relacional, cada entidad se convierte en…', 'Una tabla, con sus atributos simples univaluados como columnas y su identificador como clave primaria', ['Una columna de otra tabla', 'Una clave foránea', 'Una restricción CHECK'], 'Los identificadores alternativos pasan a ser claves alternativas.');
  Q('rel', '¿Qué se hace con los atributos derivados al transformar al modelo relacional?', 'Se ignoran (desaparecen)', ['Se convierten en tablas', 'Se vuelven claves foráneas', 'Se guardan como columnas con CHECK'], 'Se pueden calcular en una consulta cuando se necesiten.');
  Q('rel', 'Los atributos compuestos se transforman…', 'Descomponiéndolos en atributos simples (columnas)', ['En una tabla aparte con clave compuesta', 'En un único campo de texto', 'Ignorándolos'], 'Ejemplo: fechaNac → dia, mes, anio.');
  Q('rel', 'Un atributo multivaluado (por ejemplo telefono de Proveedor) se transforma en…', 'Una tabla nueva cuya clave primaria es la clave de la entidad más el atributo multivaluado', ['Una columna de tipo texto con valores separados por coma', 'Una restricción CHECK', 'Una columna con valor por defecto'], 'Proveedor(provCodigo, nombre) y Telefono(provCodigo, numtelefono).');
  Q('rel', 'Un atributo dominio cuyos valores NO cambian en el tiempo (p. ej. género F/M) se transforma en…', 'Una columna con una restricción CHECK', ['Una tabla aparte', 'Una clave foránea obligatoria', 'Un atributo derivado'], 'Si los valores pueden cambiar o crecer (tipo de inmueble), se crea una tabla nueva con una FK.');
  Q('rel', 'Un atributo dominio cuyos valores pueden crecer en el tiempo (por ejemplo tipo de inmueble) se transforma en…', 'Una tabla nueva (id, nombre) y una clave foránea en la tabla original', ['Un CHECK con la lista de valores', 'Un atributo multivaluado', 'Se elimina'], 'Así se agregan nuevos valores con un INSERT, sin modificar la estructura.');
  Q('rel', 'Regla de transformación para una relación 1:N:', 'Propagar la clave de la entidad del lado 1 como clave foránea a la tabla del lado N', ['Propagar la clave del lado N al lado 1', 'Crear siempre una tabla nueva', 'Eliminar la relación'], 'Ejemplo: Dependencia(1) – Empleado(N) → Empleado(empId, ..., depCodigo).');
  Q('rel', 'Una relación N:M se transforma en…', 'Una tabla nueva cuya clave primaria es la concatenación de las claves de las entidades, y cuyos componentes son claves foráneas', ['Una clave foránea en la tabla con mayor cardinalidad', 'Un atributo multivaluado', 'Una clave alternativa'], 'Ejemplo: Imparte(profId, codigo, fecha).');
  Q('rel', 'Relación 1:1 con cardinalidades (0,1) en ambos lados. ¿Qué conviene hacer?', 'Crear una nueva tabla para la relación, evitando valores nulos', ['Propagar la clave a cualquiera de las dos tablas', 'Fusionar las tablas', 'Ignorar la relación'], 'Ejemplo: Hombre – se_casa – Mujer: no todos están casados, propagar produciría NULLs.');
  Q('rel', 'Cada departamento tiene exactamente un responsable (profesor) y un profesor es responsable de máximo un departamento. En la transformación, la clave foránea…', 'Va en DEPARTAMENTO (profId), declarada NOT NULL', ['Va en PROFESOR (depCodigo), admite NULL', 'Va en una tabla nueva', 'No es necesaria'], 'Se propaga hacia la entidad de participación obligatoria (1,1), evitando nulos y captando más semántica.');
  Q('rel', 'Relación 1:1 con cardinalidades (1,1) en ambos lados: ¿qué es correcto?', 'Se puede propagar la clave en cualquier sentido, considerando los accesos más frecuentes', ['Obligatoriamente se crea una tabla nueva', 'Es un error de diseño', 'Debe convertirse en N:M'], 'Criterio: cuál tabla se consulta más, eficiencia, semántica.');
  Q('rel', 'Una relación reflexiva Empleado supervisa a Empleado (cada empleado tiene un único supervisor), se puede transformar como…', 'Empleado(codEmpleado, nombre, codSupervisor) con codSupervisor FK a la misma tabla', ['Empleado(codEmpleado, nombre) sin más cambios', 'Dos tablas Empleado idénticas', 'Una clave compuesta (codEmpleado, nombre)'], 'La otra solución válida es una tabla Supervisa(codSupervisor, codEmpleado) con ambas FK hacia Empleado.');
  Q('rel', 'Una relación n-aria (por ejemplo ternaria) se transforma en…', 'Una nueva tabla con las claves de todas las entidades y los atributos propios; su clave primaria es el conjunto de las claves', ['Una FK en la entidad más grande', 'Tres tablas independientes sin relación', 'Un atributo multivaluado'], 'R(idTablaA, idTablaB, idTablaC, atributoR).');
  Q('rel', 'Generalización, 1.ª opción: englobar todo en una sola tabla con un atributo discriminante. Se adopta cuando…', 'Los subtipos se diferencian en muy pocos atributos', ['Los subtipos tienen muchísimos atributos distintos', 'No existe supertipo', 'Hay solo un subtipo'], 'Ejemplo: profesor doctor y no doctor.');
  Q('rel', 'En la 1.ª opción de generalización (tabla única), el atributo discriminante…', 'Admite nulos si la jerarquía es parcial y debe ser NOT NULL si es total', ['Siempre admite nulos', 'Siempre es NOT NULL', 'Se convierte en clave primaria'], 'Total → todo ejemplar tiene subtipo → NOT NULL.');
  Q('rel', 'Generalización, 2.ª opción: una tabla para el supertipo y una por subtipo con la clave del supertipo. Se aplica generalmente cuando hay…', 'Solapamiento y parcialidad (y muchos atributos distintos)', ['Totalidad y exclusividad', 'Un solo subtipo', 'Atributos idénticos en los subtipos'], 'La clave primaria del supertipo pasa a los subtipos.');
  Q('rel', 'Generalización, 3.ª opción: tablas separadas por subtipo que incluyen los atributos comunes y NO se crea tabla del supertipo. Se aplica generalmente con…', 'Totalidad y exclusividad (y muchos atributos distintos)', ['Solapamiento y parcialidad', 'Un solo atributo común', 'Un supertipo con un solo ejemplar'], 'Profesor(id, nombre, dirección, escalafón, categoría), Estudiante(id, nombre, dirección, promedio, estado).');
  Q('rel', 'Una entidad débil con dependencia en identificación se transforma…', 'Propagando la clave de la entidad fuerte como clave foránea NOT NULL, que forma parte de la clave primaria de la débil', ['Sin ninguna clave foránea', 'Con una FK que admite NULL', 'Como una tabla independiente'], 'Curso(codCurso…), Edicion(codCurso, numEdicion, …).');
  Q('rel', 'En una tabla del modelo relacional, ¿qué NO debe ocurrir?', 'Que existan filas (tuplas) repetidas', ['Que tenga una clave primaria', 'Que tenga columnas con distinto tipo', 'Que tenga claves foráneas'], 'Una relación es un conjunto: sin tuplas repetidas.');

  /* ---------------- PG (pata de gallo) ---------------- */
  Q('pg', 'En la notación pata de gallo, el símbolo "||" (dos barras) en el extremo de una relación significa…', 'Exactamente uno', ['Cero o uno', 'Uno o muchos', 'Cero o muchos'], 'Dos barras: mínimo uno, máximo uno.');
  Q('pg', 'El símbolo "círculo + barra" (o|) significa…', 'Cero o uno', ['Exactamente uno', 'Uno o muchos', 'Cero o muchos'], 'El círculo indica que la participación es opcional (mínimo cero).');
  Q('pg', 'La "pata de gallo" con una barra (|<) significa…', 'Uno o muchos', ['Cero o muchos', 'Exactamente uno', 'Cero o uno'], 'Barra = mínimo 1; patas = máximo muchos.');
  Q('pg', 'La "pata de gallo" con un círculo (o<) significa…', 'Cero o muchos', ['Uno o muchos', 'Exactamente uno', 'Cero o uno'], 'Círculo = mínimo 0; patas = máximo muchos.');
  Q('pg', 'En un diagrama de pata de gallo, cada entidad se representa como…', 'Una tabla con sus columnas, marcando PK y FK', ['Un rombo con su nombre', 'Un óvalo', 'Un rectángulo sin atributos'], 'Pata de gallo es más cercano al modelo relacional/físico: muestra claves primarias y foráneas.');
  Q('pg', 'Al pasar de Chen a pata de gallo, una relación N:M se representa…', 'Con una entidad (tabla) asociativa entre las dos entidades, con dos relaciones 1:N', ['Con una línea directa con patas en ambos extremos y sin tabla intermedia', 'Con una clave foránea en cualquiera de las dos tablas', 'Con un atributo multivaluado'], 'La tabla intermedia contiene las dos FK (formando su PK) y los atributos de la relación.');
  Q('pg', 'En una relación 1:N dibujada en pata de gallo, ¿en qué tabla queda la clave foránea?', 'En la tabla del lado "muchos" (donde está la pata de gallo)', ['En la tabla del lado "uno"', 'En ambas tablas', 'En ninguna'], 'La FK va donde está la pata de gallo (lado N) y apunta a la PK del lado 1.');
  Q('pg', 'En el sistema de ventas de la clase, ¿qué tabla resuelve la relación N:M entre VENTA y PRODUCTO?', 'DETALLE_VENTA (cantidad, precio, id_venta, id_producto)', ['CATEGORIA', 'CLIENTE', 'No hay tabla: es una FK en VENTA'], 'DETALLE_VENTA es la entidad asociativa.');
  Q('pg', '"Cada producto pertenece a una sola categoría; una categoría tiene muchos productos". ¿Dónde va id_categoria?', 'En PRODUCTO, como clave foránea', ['En CATEGORIA, como clave foránea', 'En una tabla intermedia obligatoria', 'En DETALLE_VENTA'], '1:N: la clave del lado 1 (CATEGORIA) pasa al lado N (PRODUCTO).');
  Q('pg', 'Para una cardinalidad (1,1) del lado del hijo (cada pedido DEBE tener un cliente), la clave foránea en PEDIDO debe declararse…', 'NOT NULL', ['Admitiendo NULL', 'UNIQUE', 'Como clave primaria'], 'Participación mínima 1 → FK obligatoria.');
  Q('pg', 'En una relación 1:1 donde un lado tiene participación (0,1) y el otro (1,1), la FK…', 'Va en la tabla de participación obligatoria y debe ser UNIQUE y NOT NULL', ['Va en la de participación opcional y admite NULL', 'No se declara', 'Se declara solo con CHECK'], 'UNIQUE garantiza el máximo de uno (1:1).');
  Q('pg', 'Dos relaciones distintas entre las mismas dos entidades (p. ej. VUELO sale_de / llega_a AEROPUERTO) requieren…', 'Dos claves foráneas con nombres de columna diferentes (origen y destino)', ['Una sola clave foránea', 'Una tabla asociativa obligatoria', 'Un atributo derivado'], 'Los nombres siguen el rol: aeropuerto_origen y aeropuerto_destino.');

  /* ---------------- SQL ---------------- */
  Q('sql', 'SQL es un lenguaje…', 'Declarativo: se indica qué datos se quieren, no cómo obtenerlos', ['Procedimental: se indica paso a paso cómo obtenerlos', 'Solo para consultar, no para definir datos', 'Específico de un único SGBD'], 'Estandarizado (ISO/IEC 9075) con variaciones entre SGBD.');
  Q('sql', 'Las palabras clave de SQL (SELECT, FROM…)', 'No distinguen mayúsculas de minúsculas', ['Solo funcionan en mayúsculas', 'Solo funcionan en minúsculas', 'Distinguen mayúsculas en PostgreSQL'], 'Las convenciones de escritura (mayúsculas para entidades) son estilo, no obligación del lenguaje.');
  Q('sql', 'CREATE, ALTER y DROP pertenecen a…', 'DDL (lenguaje de definición de datos)', ['DML', 'DQL', 'DCL'], 'Crean, modifican y eliminan estructuras.');
  Q('sql', 'INSERT, UPDATE y DELETE pertenecen a…', 'DML (lenguaje de manipulación de datos)', ['DDL', 'DCL', 'TCL'], 'Insertan, modifican y eliminan filas.');
  Q('sql', 'SELECT pertenece a… (según la clasificación de la clase)', 'DQL (lenguaje de consulta de datos)', ['DDL', 'DCL', 'TCL'], 'Algunos autores lo incluyen en DML; en la clase se separa como DQL.');
  Q('sql', 'GRANT y REVOKE pertenecen a…', 'DCL (control de datos: permisos)', ['DDL', 'DML', 'DQL'], 'Otorgan y revocan permisos de acceso.');
  Q('sql', 'COMMIT y ROLLBACK pertenecen a…', 'TCL (control de transacciones)', ['DDL', 'DCL', 'DQL'], 'La clase indica que algunos autores añaden TCL.');
  Q('sql', 'Una PRIMARY KEY…', 'Identifica de forma única cada registro y no admite NULL', ['Admite valores repetidos', 'Admite NULL', 'Solo puede tener un tipo de dato numérico'], 'Es única y no nula.');
  Q('sql', '¿Cuál es la diferencia principal entre UNIQUE y PRIMARY KEY?', 'Una tabla puede tener varias columnas UNIQUE, pero una sola PRIMARY KEY; y UNIQUE (en PostgreSQL) admite NULL', ['UNIQUE permite duplicados', 'No hay diferencia', 'PRIMARY KEY permite NULL'], 'UNIQUE es la base de las claves alternativas.');
  Q('sql', 'La restricción CHECK sirve para…', 'Validar que se cumpla una condición, por ejemplo CHECK (edad >= 0)', ['Relacionar dos tablas', 'Asignar un valor por defecto', 'Impedir valores nulos'], 'Si la condición no se cumple, el SGBD rechaza la fila.');
  Q('sql', 'DEFAULT en una columna…', 'Asigna un valor predeterminado cuando no se indica otro', ['Impide valores repetidos', 'Define la clave primaria', 'Borra la columna'], 'Ejemplo: activo BOOLEAN DEFAULT TRUE.');
  Q('sql', 'Para precio con 10 dígitos en total y 2 decimales se declara…', 'NUMERIC(10,2) (o DECIMAL(10,2))', ['VARCHAR(10,2)', 'INT(10,2)', 'CHAR(12)'], 'DECIMAL(p,s)/NUMERIC(p,s) guardan números exactos con precisión definida.');
  Q('sql', 'Diferencia entre CHAR(n) y VARCHAR(n):', 'CHAR es de longitud fija; VARCHAR es de longitud variable con límite n', ['CHAR es para números y VARCHAR para fechas', 'CHAR es de longitud variable y VARCHAR fija', 'No hay diferencia'], 'Ejemplos: genero CHAR(1), nombre VARCHAR(100).');
  Q('sql', '¿Qué genera valores incrementales automáticos en PostgreSQL?', 'SERIAL', ['AUTO_INCREMENT', 'IDENTITY(1,1)', 'COUNTER'], 'AUTO_INCREMENT es de MySQL e IDENTITY de SQL Server.');
  Q('sql', 'Al crear tablas con claves foráneas, se deben crear primero…', 'Las tablas referenciadas', ['Las tablas que tienen la FK', 'Las tablas sin PRIMARY KEY', 'El orden es indiferente'], 'Si no, FOREIGN KEY ... REFERENCES fallaría porque la tabla destino aún no existe.');
  Q('sql', 'Al insertar datos con claves foráneas, se deben insertar primero…', 'Las filas referenciadas', ['Las filas que tienen la FK', 'Las filas con NULL', 'El orden es indiferente'], 'Ejemplo: primero CLIENTE, luego PEDIDO.');
  Q('sql', 'Una convención recomendada de nombres es…', 'Sustantivos en singular, sin espacios ni tildes, separando palabras con guion bajo y evitando palabras reservadas', ['Nombres con espacios y tildes para que sean legibles', 'Usar ORDER o GROUP como nombre de tabla', 'Mezclar convenciones según el caso'], 'Ejemplos: PRODUCTO, fecha_registro, nombre_completo.');
  Q('sql', 'WHERE y HAVING se diferencian en que…', 'WHERE filtra filas antes de agrupar y HAVING filtra grupos después de agrupar', ['WHERE filtra grupos y HAVING filas', 'Son sinónimos', 'HAVING solo funciona sin GROUP BY'], 'HAVING suele usarse con funciones de agregación.');
  Q('sql', 'El orden correcto de las cláusulas en una consulta es…', 'SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY', ['SELECT, WHERE, FROM, HAVING, GROUP BY, ORDER BY', 'FROM, SELECT, GROUP BY, WHERE, ORDER BY, HAVING', 'SELECT, FROM, ORDER BY, WHERE, GROUP BY, HAVING'], 'ORDER BY va siempre al final.');
  Q('sql', 'COUNT(columna) frente a COUNT(*):', 'COUNT(columna) ignora los valores NULL; COUNT(*) cuenta todas las filas', ['COUNT(*) ignora los NULL', 'Ambos ignoran NULL', 'Ninguno ignora NULL'], 'Las funciones que reciben una columna ignoran los NULL.');
  Q('sql', 'ORDER BY sin ASC ni DESC ordena…', 'De menor a mayor (ASC es el orden por defecto)', ['De mayor a menor', 'Aleatoriamente', 'Por la clave primaria'], 'DESC ordena de mayor a menor.');
  Q('sql', 'Para buscar filas con valor nulo se escribe…', 'WHERE columna IS NULL', ['WHERE columna = NULL', 'WHERE columna == NULL', 'WHERE columna LIKE NULL'], 'Cualquier comparación con = NULL da desconocido, nunca verdadero.');
  Q('sql', 'El operador "distinto de" en SQL estándar es…', '<>', ['=!', '!==', '=/='], 'Los demás: = igual, < menor, > mayor, <= y >=.');
  Q('sql', "WHERE nombre LIKE 'L%' devuelve…", "Nombres que empiezan por la letra L", ['Nombres que terminan en L', 'Nombres que contienen exactamente una L', 'Nombres de un solo carácter'], '% representa cualquier secuencia de caracteres (incluso vacía).');
  Q('sql', 'La clave PRIMARY KEY (id_pedido, id_producto) en DETALLE_PEDIDO es…', 'Compuesta: cada producto aparece una sola vez por pedido', ['Simple sobre id_pedido', 'Una clave alternativa', 'Una restricción CHECK'], 'La combinación de ambas columnas debe ser única.');
  Q('sql', 'Un DELETE sin cláusula WHERE…', 'Elimina todas las filas de la tabla (la tabla sigue existiendo)', ['Elimina la tabla', 'Genera un error de sintaxis', 'No elimina nada'], 'DROP TABLE es el que elimina la tabla completa.');
  Q('sql', 'Tabla PRODUCTO con precios 85000, 35000 y 450000. SELECT AVG(precio) FROM PRODUCTO devuelve…', '190000', ['85000', '570000', '3'], '(85000 + 35000 + 450000) / 3 = 190000.');
  Q('sql', 'Con PRODUCTO(Teclado 85000, Mouse 35000, Monitor 450000), SELECT nombre FROM PRODUCTO WHERE precio > 40000 devuelve…', 'Teclado y Monitor', ['Solo Monitor', 'Mouse y Teclado', 'Los tres productos'], '85000 y 450000 son mayores que 40000.');
  Q('sql', 'Para que PostgreSQL rechace un precio menor o igual a cero se declara…', 'precio NUMERIC(10,2) CHECK (precio > 0)', ['precio NUMERIC(10,2) UNIQUE', 'precio NUMERIC(10,2) DEFAULT 0', 'precio NUMERIC(10,2) NOT CHECK'], 'CHECK exige que se cumpla la condición.');

  /* ---------------- LAB (PostgreSQL) ---------------- */
  Q('lab', 'En la consola psql, ¿qué comando conecta a la base de datos biblioteca después de crearla?', '\\c biblioteca', ['USE biblioteca;', 'CONNECT biblioteca;', 'SELECT biblioteca;'], 'CREATE DATABASE biblioteca; y luego \\c biblioteca. USE es de MySQL.');
  Q('lab', 'Para listar los libros publicados después de 1980:', 'SELECT titulo FROM libros WHERE anio_publicacion > 1980;', ['SELECT titulo FROM libros HAVING anio_publicacion > 1980;', 'SELECT titulo FROM libros WHERE anio_publicacion = > 1980;', 'SELECT titulo FROM libros GROUP BY anio_publicacion > 1980;'], 'Filtro simple con WHERE.');
  Q('lab', 'Préstamos activos en la tabla prestamos (sin fecha de devolución):', 'SELECT * FROM prestamos WHERE fecha_devolucion IS NULL;', ['SELECT * FROM prestamos WHERE fecha_devolucion = NULL;', "SELECT * FROM prestamos WHERE fecha_devolucion = '';", 'SELECT * FROM prestamos WHERE fecha_devolucion = 0;'], 'Se usa IS NULL.');
  Q('lab', "Usuarios con correo de gmail:", "SELECT * FROM usuarios WHERE correo LIKE '%@gmail.com';", ["SELECT * FROM usuarios WHERE correo = '%@gmail.com';", "SELECT * FROM usuarios WHERE correo IN '@gmail.com';", "SELECT * FROM usuarios WHERE correo ~~ gmail;"], 'LIKE con % como comodín.');
  Q('lab', 'Autor del libro \'Cien años de soledad\':', "SELECT a.nombre FROM libros l JOIN autores a ON a.id_autor = l.id_autor WHERE l.titulo = 'Cien años de soledad';", ["SELECT nombre FROM libros WHERE titulo = 'Cien años de soledad';", "SELECT a.nombre FROM autores a WHERE a.titulo = 'Cien años de soledad';", "SELECT id_autor FROM autores JOIN libros;"], 'Se unen libros y autores por la clave foránea id_autor.');
  Q('lab', 'Libros que nunca se han prestado:', 'SELECT l.titulo FROM libros l LEFT JOIN prestamos p ON p.id_libro = l.id_libro WHERE p.id_prestamo IS NULL;', ['SELECT l.titulo FROM libros l JOIN prestamos p ON p.id_libro = l.id_libro;', 'SELECT titulo FROM libros WHERE id_libro = NULL;', 'SELECT titulo FROM libros GROUP BY id_libro HAVING COUNT(*) = 0;'], 'LEFT JOIN conserva libros sin préstamo, que quedan con NULL en prestamos.');
  Q('lab', 'Agregar la columna género a la tabla libros:', 'ALTER TABLE libros ADD genero VARCHAR(50);', ['UPDATE libros ADD genero VARCHAR(50);', 'INSERT INTO libros genero VARCHAR(50);', 'CREATE COLUMN genero ON libros;'], 'Cambiar la estructura es DDL: ALTER TABLE.');
  Q('lab', "Marcar como 'Devuelto' los préstamos con fecha de devolución:", "UPDATE prestamos SET estado = 'Devuelto' WHERE fecha_devolucion IS NOT NULL;", ["ALTER prestamos SET estado = 'Devuelto';", "INSERT INTO prestamos (estado) VALUES ('Devuelto');", "UPDATE prestamos estado = 'Devuelto' IF fecha_devolucion;"], 'UPDATE ... SET ... WHERE.');
  Q('lab', 'Número de préstamos por estado:', 'SELECT estado, COUNT(*) FROM prestamos GROUP BY estado;', ['SELECT estado, COUNT(*) FROM prestamos ORDER BY estado HAVING COUNT(*);', 'SELECT COUNT(estado) FROM prestamos WHERE estado;', 'SELECT estado FROM prestamos GROUP;'], 'GROUP BY agrupa; COUNT(*) se calcula por grupo.');
  Q('lab', 'Usuario con más préstamos:', 'SELECT u.nombre, COUNT(*) AS total FROM usuarios u JOIN prestamos p ON p.id_usuario = u.id_usuario GROUP BY u.id_usuario, u.nombre ORDER BY total DESC LIMIT 1;', ['SELECT nombre, MAX(prestamos) FROM usuarios;', 'SELECT u.nombre FROM usuarios u WHERE COUNT(*) = MAX;', 'SELECT u.nombre, COUNT(*) FROM usuarios u ORDER BY 1 LIMIT 1;'], 'Agrupar por usuario, ordenar descendente por el conteo y limitar a 1.');
  Q('lab', 'Polideportivo: no se pueden registrar socios menores de 5 años. La sentencia correcta es…', 'ALTER TABLE socios ADD CONSTRAINT ck_socios_edad CHECK (edad >= 5);', ['ALTER TABLE socios ADD edad >= 5;', 'UPDATE socios SET edad >= 5;', 'CREATE CHECK socios (edad >= 5);'], 'Una restricción de tabla ya creada se añade con ALTER TABLE ... ADD CONSTRAINT.');
  Q('lab', 'Polideportivo: eliminar por completo la tabla eventos para ahorrar recursos:', 'DROP TABLE eventos;', ['DELETE FROM eventos;', 'TRUNCATE eventos CASCADE FROM socios;', 'ALTER TABLE eventos DROP;'], 'DELETE vacía la tabla, DROP TABLE la elimina.');
  Q('lab', 'Polideportivo: socios Premium o VIP mayores de 20 años:', "SELECT * FROM socios WHERE tipo_membresia IN ('Premium','VIP') AND edad > 20;", ["SELECT * FROM socios WHERE tipo_membresia = 'Premium' OR 'VIP' AND edad > 20;", "SELECT * FROM socios WHERE tipo_membresia = 'Premium' AND 'VIP' AND edad > 20;", "SELECT * FROM socios HAVING edad > 20 AND tipo_membresia IN ('Premium','VIP');"], 'IN evita errores de precedencia entre AND y OR.');
  Q('lab', 'Polideportivo: eliminar los entrenadores que ya no están activos (activo es BOOLEAN):', 'DELETE FROM entrenadores WHERE activo = FALSE;', ['DROP entrenadores WHERE activo = FALSE;', 'DELETE entrenadores.activo;', 'UPDATE entrenadores DELETE WHERE activo = FALSE;'], 'DELETE FROM tabla WHERE condición.');
  Q('lab', "Polideportivo: entrenadores cuyo nombre comienza con 'L':", "SELECT * FROM entrenadores WHERE nombre LIKE 'L%';", ["SELECT * FROM entrenadores WHERE nombre = 'L';", "SELECT * FROM entrenadores WHERE nombre LIKE '%L';", "SELECT * FROM entrenadores WHERE nombre STARTS 'L';"], "'L%' = empieza por L.");

  /* ---------------- NORM ---------------- */
  Q('norm', 'El objetivo principal de la normalización es…', 'Reducir la redundancia y evitar anomalías de inserción, actualización y eliminación', ['Aumentar el número de tablas sin justificación', 'Acelerar siempre todas las consultas', 'Eliminar las claves foráneas'], 'También mantiene la integridad y facilita el mantenimiento.');
  Q('norm', 'La dependencia funcional X → Y significa que…', 'Cada valor de X determina un único valor de Y', ['Y determina muchos valores de X', 'X e Y son siempre claves primarias', 'X contiene a Y como subcadena'], 'Ejemplo: id_cliente → nombre.');
  Q('norm', 'Una tabla está en Primera Forma Normal (1FN) si…', 'Todos sus atributos tienen valores atómicos y no hay grupos repetitivos', ['Ningún atributo no primo depende de una parte de la clave', 'No existen dependencias transitivas', 'Tiene exactamente dos claves candidatas'], 'Cada celda tiene un solo valor, no hay columnas como producto1 y producto2, y cada fila se identifica por una clave.');
  Q('norm', 'Una celda con el valor "101, 102" en id_producto…', 'Viola la 1FN porque no es atómica', ['Cumple 1FN', 'Viola la 3FN pero no la 1FN', 'Es válida si la columna es VARCHAR'], 'Debe haber una fila por producto del pedido.');
  Q('norm', 'Una tabla está en Segunda Forma Normal (2FN) si…', 'Está en 1FN y ningún atributo no primo depende solo de una parte de una clave candidata compuesta', ['Está en 3FN', 'No tiene claves foráneas', 'Todos sus atributos son claves'], 'Con una clave candidata simple, una tabla en 1FN ya cumple 2FN.');
  Q('norm', 'Una tabla está en Tercera Forma Normal (3FN) si…', 'Está en 2FN y ningún atributo no primo depende transitivamente de una clave candidata', ['Está en 1FN y tiene clave compuesta', 'No tiene atributos opcionales', 'Solo tiene dos columnas'], 'Transitiva: clave → atributo no clave → otro atributo.');
  Q('norm', 'Un atributo primo es…', 'Un atributo que pertenece a alguna clave candidata', ['Un atributo numérico', 'Un atributo derivado', 'Un atributo opcional'], 'Atributo no primo: no forma parte de ninguna clave candidata.');
  Q('norm', 'En VENTAS(id_pedido, id_producto, fecha, id_cliente, nombre_cliente, email, nombre_producto, precio, cantidad) con clave (id_pedido, id_producto), id_producto → nombre_producto, precio es una dependencia…', 'Parcial: por eso la tabla no cumple 2FN', ['Total: la tabla cumple 2FN', 'Transitiva: la tabla no cumple 3FN pero sí 2FN', 'Irrelevante para la normalización'], 'Dependencia de una parte de la clave = parcial → viola 2FN.');
  Q('norm', 'En PEDIDO_CLIENTE(id_pedido PK, fecha, id_cliente, nombre_cliente, email): id_pedido → id_cliente → nombre_cliente. Esa dependencia es…', 'Transitiva: la tabla no cumple 3FN', ['Parcial: no cumple 2FN', 'Total: cumple 3FN', 'Una anomalía de 1FN'], 'Corrección: PEDIDO(id_pedido, fecha, id_cliente) y CLIENTE(id_cliente, nombre, email).');
  Q('norm', 'Anomalía de ELIMINACIÓN en la tabla VENTAS sin normalizar:', 'Al borrar el único pedido de un cliente se pierde también la información de ese cliente', ['No se puede registrar un cliente sin pedidos', 'Cambiar el email obliga a modificar varias filas', 'Hay celdas con varios valores'], 'La de inserción: no se puede registrar a un cliente sin pedidos. La de actualización: modificar varias filas.');
  Q('norm', 'Anomalía de ACTUALIZACIÓN en VENTAS sin normalizar:', 'Cambiar el email de un cliente exige modificar varias filas; si se omite alguna quedan datos inconsistentes', ['No se puede insertar un cliente sin pedidos', 'Al borrar un pedido se pierde un cliente', 'Las celdas no son atómicas'], 'Por la redundancia de datos repetidos.');
  Q('norm', 'Una buena normalización debe…', 'Justificar cada división con dependencias funcionales y claves, y conservar la información (el JOIN reconstruye la tabla original)', ['Dividir tablas todo lo posible', 'Eliminar las claves foráneas', 'Reducir siempre el número de tablas'], '"Normalizar no consiste simplemente en dividir tablas".');
  Q('norm', 'PRODUCTO_CATEGORIA(id_producto PK, nombre, precio, id_categoria, nombre_categoria) con id_categoria → nombre_categoria cumple…', '1FN y 2FN, pero no 3FN', ['1FN, 2FN y 3FN', 'Solo 1FN', 'Ninguna forma normal'], 'Clave simple → 2FN; pero id_producto → id_categoria → nombre_categoria es transitiva.');
  Q('norm', 'La solución a 3FN de PRODUCTO_CATEGORIA es…', 'CATEGORIA(id_categoria PK, nombre) y PRODUCTO(id_producto PK, nombre, precio, id_categoria FK)', ['Una sola tabla con todas las columnas', 'PRODUCTO(id_producto, nombre) y PRECIO(precio, id_categoria)', 'CATEGORIA(id_producto, nombre_categoria) únicamente'], 'Se separan los atributos que dependen de id_categoria.');

  /* ---------------- Preguntas abiertas ---------------- */
  const OPEN = [
    { id: 'o1', t: 'met', q: 'Explique las etapas de la metodología de diseño de una base de datos, desde el universo del discurso hasta el modelo físico.', a: ['<b>Universo del Discurso (UD):</b> la realidad a modelar, obtenida de las vistas de los usuarios.', '<b>Modelo conceptual (E/R de Chen, 1976):</b> vista abstracta y global en entidades, atributos y relaciones; independiente del SGBD.', '<b>Modelo lógico (relacional, Codd 1970):</b> estructura lógica en tablas, claves primarias y foráneas.', '<b>Normalización:</b> perfecciona el modelo relacional para eliminar redundancia.', '<b>Modelo físico:</b> implementación en un SGBD concreto con DDL, índices y restricciones.'] },
    { id: 'o2', t: 'er', q: 'Diferencie cardinalidad y correspondencia en el modelo E/R y dé un ejemplo.', a: ['<b>Cardinalidad:</b> pareja (mínimo, máximo) de participación de una entidad en una relación: (0,1), (1,1), (0,n), (1,n).', '<b>Correspondencia:</b> el número MÁXIMO de ejemplares con los que se relaciona un ejemplar: 1:1, 1:N, N:M. Se obtiene de los máximos de las cardinalidades.', 'Ejemplo: Profesor (1,n) imparte (0,n) Curso → correspondencia N:M. Dirige (1,1)–(1,1) → 1:1.'] },
    { id: 'o3', t: 'avz', q: 'Explique la diferencia entre dependencia en existencia y dependencia en identificación. Dé un ejemplo de cada una.', a: ['<b>Existencia:</b> los ejemplares de la entidad débil no pueden existir sin el ejemplar de la entidad fuerte. Ej.: Cuenta depende de Cliente.', '<b>Identificación:</b> además, la entidad débil no se identifica por sí misma y necesita la clave de la fuerte. Ej.: Edición se identifica con (cod_Curso, num_Edicion).', 'Toda dependencia en identificación es de existencia, pero no al revés.', 'Transformación: propagar la clave de la fuerte como FK NOT NULL (y en identificación, parte de la PK de la débil).'] },
    { id: 'o4', t: 'avz', q: 'Defina solapamiento, exclusividad, totalidad y parcialidad en una especialización y dé un ejemplo de cada una.', a: ['<b>Solapamiento:</b> un ejemplar puede pertenecer a más de un subtipo (Persona es Profesor y Estudiante).', '<b>Exclusividad:</b> solo puede pertenecer a UNO (Profesor de Planta u Ocasional).', '<b>Totalidad:</b> todo ejemplar del supertipo debe pertenecer a algún subtipo (Empleado es Profesor o Administrativo).', '<b>Parcialidad:</b> no es obligatorio que pertenezca a un subtipo.'] },
    { id: 'o5', t: 'avz', q: 'Distinga las restricciones de exclusividad, exclusión, inclusividad e inclusión entre interrelaciones. Dé un ejemplo de cada una.', a: ['<b>Exclusividad:</b> un ejemplar de A se relaciona a través de R1 o R2, pero no ambas (proyecto asignado a empleados o a contratistas).', '<b>Exclusión:</b> el mismo par (a1, b1) no puede estar en R1 y en R2 (profesor no imparte y se capacita en el mismo curso).', '<b>Inclusividad:</b> todo ejemplar de A en R2 debió participar en R1 con algún ejemplar de B (impartir exige haberse capacitado en algún curso).', '<b>Inclusión:</b> el par (a1, b1) debió estar antes en R1 para estar en R2 (liquidar a una persona exige haberla contratado en esa empresa).'] },
    { id: 'o6', t: 'rel', q: 'Describa las reglas para transformar al modelo relacional: entidades, atributos multivaluados, relaciones 1:N y relaciones N:M.', a: ['<b>Entidades:</b> tabla; atributos simples → columnas; identificador → PK; alternativos → UNIQUE.', '<b>Multivaluado:</b> tabla nueva con PK = clave de la entidad + el atributo.', '<b>1:N:</b> propagar la PK del lado 1 como FK al lado N (NOT NULL si la participación mínima es 1).', '<b>N:M:</b> tabla nueva con PK compuesta por las claves de ambas entidades (ambas FK) y los atributos de la relación.'] },
    { id: 'o7', t: 'rel', q: 'Explique las tres estrategias de transformación de una generalización/especialización y cuándo se aplica cada una.', a: ['<b>1.ª opción – tabla única:</b> todos los atributos en una tabla con atributo discriminante; cuando los subtipos difieren en pocos atributos. Discriminante NOT NULL si es total.', '<b>2.ª opción – supertipo + una tabla por subtipo:</b> la PK del supertipo pasa a los subtipos; muchos atributos distintos; típico con solapamiento y parcialidad.', '<b>3.ª opción – solo tablas de subtipos con atributos comunes:</b> sin tabla de supertipo; muchos atributos distintos; típico con totalidad y exclusividad.'] },
    { id: 'o8', t: 'rel', q: 'Explique cómo se transforma una relación 1:1 según las cardinalidades mínimas: (0,1)-(0,1), (0,1)-(1,1) y (1,1)-(1,1).', a: ['<b>(0,1)-(0,1):</b> tabla nueva con las dos claves (evita NULLs).', '<b>(0,1)-(1,1):</b> propagar la clave a la tabla de participación obligatoria (1,1) como FK NOT NULL (y UNIQUE).', '<b>(1,1)-(1,1):</b> se puede propagar en cualquier sentido; se decide por accesos más frecuentes y prioritarios.'] },
    { id: 'o9', t: 'pg', q: 'Explique cómo se pasa un diagrama de Chen a uno de Pata de Gallo, incluyendo la cardinalidad (símbolos) y el tratamiento de las relaciones N:M.', a: ['Cada entidad se convierte en una tabla con sus PK y FK.', 'Las relaciones 1:N se dibujan con la pata de gallo en el lado N, donde queda la FK.', 'Las N:M se transforman en una entidad asociativa con dos relaciones 1:N; su PK es la unión de las dos FK.', 'Símbolos: || exactamente uno, o| cero o uno, |< uno o muchos, o< cero o muchos.', 'Se verifica que el modelo conserve la estructura y las reglas del negocio.'] },
    { id: 'o10', t: 'sql', q: 'Diferencie DDL, DML, DQL, DCL y TCL con sus sentencias típicas.', a: ['<b>DDL</b> (definición): CREATE, ALTER, DROP.', '<b>DML</b> (manipulación): INSERT, UPDATE, DELETE.', '<b>DQL</b> (consulta): SELECT.', '<b>DCL</b> (control de permisos): GRANT, REVOKE.', '<b>TCL</b> (transacciones): COMMIT, ROLLBACK.'] },
    { id: 'o11', t: 'sql', q: 'Explique la diferencia entre WHERE y HAVING y escriba el orden de las cláusulas de una consulta.', a: ['WHERE filtra filas ANTES de agrupar; HAVING filtra grupos DESPUÉS de agrupar (usa funciones de agregación).', 'Orden: SELECT, FROM, WHERE, GROUP BY, HAVING, ORDER BY.', 'Ejemplo: SELECT id_cliente, COUNT(*) FROM PEDIDO GROUP BY id_cliente HAVING COUNT(*) > 1;'] },
    { id: 'o12', t: 'sql', q: 'Mencione cinco restricciones de integridad en SQL y explique para qué sirve cada una.', a: ['<b>PRIMARY KEY:</b> identifica de forma única cada registro (única y no nula).', '<b>FOREIGN KEY:</b> vincula una tabla con la PK de otra.', '<b>NOT NULL:</b> impide valores nulos.', '<b>UNIQUE:</b> evita valores duplicados.', '<b>CHECK:</b> valida una condición (edad >= 0).', '<b>DEFAULT:</b> valor predeterminado.'] },
    { id: 'o13', t: 'sql', q: '¿Qué diferencia hay entre DELETE, DROP TABLE y ALTER TABLE?', a: ['<b>DELETE</b> (DML) elimina filas; sin WHERE las elimina todas, pero la tabla sigue existiendo.', '<b>DROP TABLE</b> (DDL) elimina la tabla completa: estructura y datos.', '<b>ALTER TABLE</b> (DDL) modifica la estructura: agregar/eliminar columnas o restricciones.'] },
    { id: 'o14', t: 'norm', q: 'Defina normalización y explique las anomalías de inserción, actualización y eliminación con un ejemplo.', a: ['Normalización: proceso que organiza atributos y tablas según formas normales para reducir redundancia y anomalías.', 'Ejemplo con VENTAS (cliente repetido en cada fila): <b>inserción</b>: no se registra un cliente sin pedido; <b>actualización</b>: cambiar el email obliga a editar varias filas; <b>eliminación</b>: al borrar el único pedido se pierde la información del cliente.'] },
    { id: 'o15', t: 'norm', q: 'Explique 1FN, 2FN y 3FN indicando qué problema corrige cada una.', a: ['<b>1FN:</b> valores atómicos, sin grupos repetitivos, clave definida.', '<b>2FN:</b> 1FN + sin dependencias parciales (atributo no primo que depende de parte de una clave compuesta).', '<b>3FN:</b> 2FN + sin dependencias transitivas (atributo no primo que depende de otro atributo no primo).', 'Con clave simple, 1FN ya implica 2FN.'] },
    { id: 'o16', t: 'norm', q: 'La tabla PRODUCTO_CATEGORIA(id_producto PK, nombre, precio, id_categoria, nombre_categoria) tiene la DF adicional id_categoria → nombre_categoria. Liste las DF, indique qué formas normales cumple y proponga las tablas.', a: ['DF: id_producto → nombre, precio, id_categoria, nombre_categoria; id_categoria → nombre_categoria.', '1FN: sí. 2FN: sí (clave simple). 3FN: no (id_producto → id_categoria → nombre_categoria es transitiva).', 'Tablas: CATEGORIA(id_categoria PK, nombre); PRODUCTO(id_producto PK, nombre, precio, id_categoria FK).'] },
    { id: 'o17', t: 'er', q: 'Mencione los tipos de atributos del modelo E/R (simple, compuesto, multivaluado, derivado, opcional, clave) y cómo se transforma cada uno al modelo relacional.', a: ['Simple univaluado → columna.', 'Compuesto → varias columnas simples.', 'Multivaluado → tabla nueva (PK = clave de la entidad + atributo).', 'Derivado → se ignora.', 'Opcional → columna sin NOT NULL.', 'Clave principal → PRIMARY KEY; clave alternativa → UNIQUE.', 'Dominio → CHECK (si es fijo) o tabla nueva con FK (si crece).'] },
    { id: 'o18', t: 'avz', q: '¿Cuándo se usa una relación ternaria y cuándo una agregación? Dé un ejemplo de cada una.', a: ['<b>Ternaria:</b> participan tres entidades y existen 6 lecturas coherentes; típica N:M en el tiempo. Ej.: un médico programa una cirugía en un quirófano.', '<b>Agregación:</b> cuando se necesita relacionar una interrelación con otra entidad. Ej.: Profesor explica Asignatura (agregación Explicación) y utiliza Medio.'] },
    { id: 'o19', t: 'rel', q: 'Transforme al modelo relacional una relación reflexiva Empleado supervisa a Empleado y muestre las dos soluciones válidas.', a: ['<b>Solución 1:</b> Empleado(codEmpleado, nombre, codSupervisor) con codSupervisor FK a Empleado (admite NULL para quien no tiene supervisor).', '<b>Solución 2:</b> Empleado(codEmpleado, nombre) y Supervisa(codSupervisor, codEmpleado), ambas FK hacia Empleado y juntas forman la PK.', 'En ambos casos el nombre de la columna cambia según el rol.'] },
    { id: 'o20', t: 'lab', q: 'Escriba el DDL para crear una tabla libros relacionada con autores (PK serial, FK al autor, título obligatorio), y explique el orden de creación.', a: ['CREATE TABLE autores (id_autor SERIAL PRIMARY KEY, nombre VARCHAR(100) NOT NULL);', 'CREATE TABLE libros (id_libro SERIAL PRIMARY KEY, titulo VARCHAR(150) NOT NULL, id_autor INT, FOREIGN KEY (id_autor) REFERENCES autores(id_autor));', 'Primero autores (referenciada) y luego libros (tiene la FK).'] }
  ];

  /* ---------------- Ejercicios de normalización ---------------- */
  const NORM_EX = [
    {
      id: 'n1', title: 'MATRICULA_GENERAL (clave compuesta)',
      table: 'MATRICULA_GENERAL(id_estudiante, id_curso, nombre_estudiante, nombre_curso, creditos, nota)\nPK: (id_estudiante, id_curso)',
      ask: 'Liste las dependencias funcionales, indique si cumple 1FN, 2FN y 3FN y proponga las tablas.',
      sol: ['<b>DF:</b> (id_estudiante, id_curso) → nota; id_estudiante → nombre_estudiante; id_curso → nombre_curso, creditos.', '<b>1FN:</b> sí. <b>2FN:</b> NO: nombre_estudiante depende solo de id_estudiante y nombre_curso/creditos solo de id_curso (dependencias parciales).', '<b>Solución:</b> ESTUDIANTE(id_estudiante PK, nombre) · CURSO(id_curso PK, nombre, creditos) · MATRICULA(id_estudiante PK/FK, id_curso PK/FK, nota). Cada tabla ya cumple 3FN.']
    },
    {
      id: 'n2', title: 'PEDIDO_ENVIO (clave simple, dos transitivas)',
      table: 'PEDIDO_ENVIO(id_pedido, fecha, id_cliente, nombre_cliente, ciudad_cliente, id_transportadora, nombre_transportadora)\nPK: id_pedido',
      ask: 'Liste las dependencias funcionales, indique qué forma normal se viola y normalice.',
      sol: ['<b>DF:</b> id_pedido → fecha, id_cliente, id_transportadora; id_cliente → nombre_cliente, ciudad_cliente; id_transportadora → nombre_transportadora.', '<b>1FN:</b> sí. <b>2FN:</b> sí (clave simple). <b>3FN:</b> NO: hay dos dependencias transitivas (id_pedido → id_cliente → nombre/ciudad y id_pedido → id_transportadora → nombre).', '<b>Solución:</b> CLIENTE(id_cliente PK, nombre, ciudad) · TRANSPORTADORA(id_transportadora PK, nombre) · PEDIDO(id_pedido PK, fecha, id_cliente FK, id_transportadora FK).']
    },
    {
      id: 'n3', title: 'EMPLEADO_TEL (valores no atómicos)',
      table: 'EMPLEADO_TEL(id_empleado, nombre, telefonos)\nEjemplo de fila: (7, "Ana Díaz", "3001234567, 3109876543")',
      ask: '¿Qué forma normal se viola? Corrija el diseño.',
      sol: ['<b>Viola 1FN:</b> la columna telefonos contiene varios valores en una celda (no es atómica).', '<b>Solución:</b> EMPLEADO(id_empleado PK, nombre) · TELEFONO_EMPLEADO(id_empleado PK/FK, telefono PK). Es la misma transformación de un atributo multivaluado.']
    },
    {
      id: 'n4', title: 'VENTAS (ejemplo de clase)',
      table: 'VENTAS(id_pedido, id_producto, fecha, id_cliente, nombre_cliente, email, nombre_producto, precio, cantidad)\nPK: (id_pedido, id_producto)',
      ask: 'Lleve la tabla hasta 3FN justificando cada paso.',
      sol: ['<b>1FN:</b> cumple. <b>2FN:</b> NO: id_pedido → fecha, id_cliente, nombre_cliente, email (parcial) e id_producto → nombre_producto, precio (parcial).', '<b>A 2FN:</b> PEDIDO_CLIENTE(id_pedido PK, fecha, id_cliente, nombre_cliente, email) · PRODUCTO(id_producto PK, nombre, precio) · DETALLE_PEDIDO(id_pedido, id_producto, cantidad).', '<b>A 3FN:</b> en PEDIDO_CLIENTE, id_pedido → id_cliente → nombre_cliente, email (transitiva): separar CLIENTE(id_cliente PK, nombre, email) y PEDIDO(id_pedido PK, fecha, id_cliente FK).', '<b>Esquema final:</b> CLIENTE · PEDIDO · PRODUCTO · DETALLE_PEDIDO.']
    }
  ];

  window.TOPICS = TOPICS;
  window.BANK = bank;
  window.OPEN = OPEN;
  window.NORM_EX = NORM_EX;
})();
